def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    char_id = {ch: i for i, ch in enumerate(alphabet)}
    width = len(alphabet)

    transitions = [[-1] * width]
    failure = [0]
    forbidden = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_id[ch]
            if transitions[node][c] == -1:
                transitions[node][c] = len(transitions)
                transitions.append([-1] * width)
                failure.append(0)
                forbidden.append(False)
            node = transitions[node][c]
        forbidden[node] = True

    queue = deque()
    for c in range(width):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        node = queue.popleft()
        forbidden[node] |= forbidden[failure[node]]

        for c in range(width):
            child = transitions[node][c]
            if child == -1:
                transitions[node][c] = transitions[failure[node]][c]
            else:
                failure[child] = transitions[failure[node]][c]
                queue.append(child)

    states = [node for node in range(len(transitions)) if not forbidden[node]]
    index = {node: i for i, node in enumerate(states)}
    size = len(states)

    matrix = [[0] * size for _ in range(size)]
    for i, node in enumerate(states):
        for target in transitions[node]:
            if not forbidden[target]:
                matrix[i][index[target]] += 1

    def multiply(left, right):
        result = [[0] * size for _ in range(size)]
        for i, row in enumerate(left):
            output = result[i]
            for k, value in enumerate(row):
                if value:
                    for j, other in enumerate(right[k]):
                        output[j] += value * other
            for j in range(size):
                output[j] %= MOD
        return result

    counts = [0] * size
    counts[index[0]] = 1

    while n:
        if n & 1:
            updated = [0] * size
            for i, count in enumerate(counts):
                if count:
                    for j, ways in enumerate(matrix[i]):
                        updated[j] += count * ways
            counts = [value % MOD for value in updated]

        n >>= 1
        if n:
            matrix = multiply(matrix, matrix)

    return sum(counts) % MOD
